    Bug 1970899 - Show visual indicator of disabled input in address books sync view. r=aleca,freaktechnik


    **How to test**
    - Open address book account hub
    - click sync accounts
    - select an account
    - if there are existing address books, you should see a disabled input, if not open your inspector and manually disable one of the inputs

    Differential Revision: https://phabricator.services.mozilla.com/D253553

diff --git a/mail/themes/shared/mail/accountHubForms.css b/mail/themes/shared/mail/accountHubForms.css
index 96e8108bc2f..636a08db5f9 100644
--- a/mail/themes/shared/mail/accountHubForms.css
+++ b/mail/themes/shared/mail/accountHubForms.css
@@ -41,12 +41,18 @@ form {
     }
   }

-  input[type="checkbox"]:checked:enabled {
+  input[type="checkbox"]:checked {
+    -moz-context-properties: fill;
+    content: url("chrome://messenger/skin/overrides/check.svg");
     background-color: var(--color-primary-default);
     border-color: var(--color-primary-hover);
-    -moz-context-properties: fill;
     fill: var(--color-neutral-base);
-    content: url("chrome://messenger/skin/overrides/check.svg");
+
+    &:disabled {
+      background-color: var(--color-neutral-border);
+      border-color: var(--color-neutral-border);
+      fill: var(--color-text-muted);
+    }
   }

   .checkbox-label {
@@ -782,6 +788,14 @@ div:has(legend) {
       color: var(--color-text-base);
       font-weight: 400;
     }
+
+    &:has(input:disabled) {
+      pointer-events: none;
+
+      & span {
+        color: var(--color-text-muted);
+      }
+    }
   }
 }
